from __future__ import annotations

import io
import json
import os
from pathlib import PurePosixPath
from typing import Any

import modal

from src.youtube.transcribe import (
    MODEL_DIR,
    MODEL_NAME,
    MODEL_REVISION,
    WHISPER_BATCH_SIZE,
    WHISPER_GPU,
    build_generate_kwargs,
    model_cache,
)
from src.youtube.transcribe import image as base_image

R2_BUCKET: str = "epic-sermons-raw"
R2_PREFIX: str = "CMUDatabaseGroup/assets/"
OUTPUT_DIR: str = "/transcripts"
MAX_CONTAINERS: int = int(os.environ.get("WHISPER_MAX_CONTAINERS", "8"))

transcripts: modal.Volume = modal.Volume.from_name(
    "cmu-transcripts",
    create_if_missing=True,
)

r2_secret: modal.Secret = REDACTED
    "r2-epic-sermons",
    required_keys=["R2_ACCOUNT_ID", "R2_ACCESS_KEY_ID", "R2_SECRET_ACCESS_KEY"],
)

image: modal.Image = base_image.pip_install("boto3==1.35.99")

app: modal.App = modal.App(
    name="youtube-transcription-r2",
    image=image,
    volumes={MODEL_DIR: model_cache, OUTPUT_DIR: transcripts},
    secrets=[r2_secret],
)


def output_name_for_key(key: str) -> str:
    stem: str = PurePosixPath(key).stem

    return f"{stem}·transcription.json"


def test_output_name_for_key() -> None:
    key: str = "CMUDatabaseGroup/assets/2016-05-16·01dPh1gZ3cc.mp3"

    assert output_name_for_key(key) == "2016-05-16·01dPh1gZ3cc·transcription.json"


def make_r2_client() -> Any:
    import boto3

    return boto3.client(
        "s3",
        endpoint_url=f"https://{os.environ['R2_ACCOUNT_ID']}.r2.cloudflarestorage.com",
        aws_access_key_id=REDACTED,
        aws_secret_access_key=REDACTED,
        region_name="auto",
    )


def build_segments(chunks: list[dict[str, Any]]) -> list[dict[str, Any]]:
    segments: list[dict[str, Any]] = []

    for chunk in chunks:
        timestamp: tuple[Any, Any] = chunk.get("timestamp", (None, None))

        start_time: float = 0.0

        if timestamp[0] is not None:
            start_time = float(timestamp[0])

        end_time: float = start_time

        if timestamp[1] is not None:
            end_time = float(timestamp[1])

        elif len(segments) > 0:
            end_time = segments[-1]["end"]

        segments.append(
            {
                "start": start_time,
                "end": end_time,
                "text": chunk["text"],
            },
        )

    return segments


def test_build_segments() -> None:
    chunks: list[dict[str, Any]] = [
        {"timestamp": (0.0, 2.0), "text": "a"},
        {"timestamp": (2.0, None), "text": "b"},
    ]
    segments: list[dict[str, Any]] = build_segments(chunks)

    assert segments[0] == {"start": 0.0, "end": 2.0, "text": "a"}
    assert segments[1]["end"] == 2.0


@app.cls(
    gpu=WHISPER_GPU,
    timeout=2 * 60 * 60,
    scaledown_window=2 * 60,
    REDACTED,
    retries=2,
)
class WhisperR2:
    @modal.enter()
    def load_model(self) -> None:
        import torch
        from transformers import (
            AutoModelForSpeechSeq2Seq,
            AutoProcessor,
            pipeline,
        )

        processor = AutoProcessor.from_pretrained(
            MODEL_NAME,
            revision=MODEL_REVISION,
        )
        model = AutoModelForSpeechSeq2Seq.from_pretrained(
            MODEL_NAME,
            torch_dtype=torch.float16,
            low_cpu_mem_usage=True,
            use_safetensors=True,
            revision=MODEL_REVISION,
        ).to("cuda")

        self.pipe = pipeline(
            "automatic-speech-recognition",
            model=model,
            tokenizer=processor.tokenizer,
            feature_extractor=processor.feature_extractor,
            torch_dtype=torch.float16,
            device="cuda",
            return_timestamps=True,
            chunk_length_s=30,
            stride_length_s=5,
        )
        self.r2 = make_r2_client()

    @modal.method()
    def transcribe_key(self, key: str) -> dict[str, Any]:
        import librosa

        out_path: str = os.path.join(OUTPUT_DIR, output_name_for_key(key))

        transcripts.reload()

        if os.path.exists(out_path):
            return {"key": key, "status": "skipped"}

        try:
            body: bytes = self.r2.get_object(Bucket=R2_BUCKET, Key=key)["Body"].read()
            audio_array, _ = librosa.load(io.BytesIO(body), sr=16000, mono=True)
            result: dict[str, Any] = self.pipe(
                audio_array,
                return_timestamps=True,
                generate_kwargs=build_generate_kwargs(prompt_ids=None),
                batch_size=WHISPER_BATCH_SIZE,
            )
            output: dict[str, Any] = {
                "file_path": key,
                "text": result["text"],
                "segments": build_segments(result.get("chunks", [])),
                "language": "en",
            }
            tmp_path: str = f"{out_path}.tmp"

            with open(tmp_path, "w", encoding="utf-8") as f:
                json.dump(output, f, indent=2, ensure_ascii=False)

            os.replace(tmp_path, out_path)
            transcripts.commit()

            return {"key": key, "status": "success"}

        except Exception as e:
            print(f"[ERROR] {key}: {e}")

            return {"key": key, "status": "error", "message": str(e)}


def list_mp3_keys() -> list[str]:
    client: Any = make_r2_client()
    keys: list[str] = []

    for page in client.get_paginator("list_objects_v2").paginate(
        Bucket=R2_BUCKET,
        Prefix=R2_PREFIX,
    ):
        for item in page.get("Contents", []):
            if item["Key"].endswith(".mp3"):
                keys.append(item["Key"])

    return sorted(keys)


@app.function(timeout=24 * 60 * 60)
def run_all(max_files: int = 0) -> dict[str, int]:
    transcripts.reload()

    pending: list[str] = [
        key
        for key in list_mp3_keys()
        if not os.path.exists(os.path.join(OUTPUT_DIR, output_name_for_key(key)))
    ]

    if max_files > 0:
        pending = pending[:max_files]

    print(f"[INFO] {len(pending)} lectures pending")

    counts: dict[str, int] = {"success": 0, "error": 0, "skipped": 0}

    for result in WhisperR2().transcribe_key.map(
        pending,
        order_outputs=False,
        return_exceptions=True,
    ):
        match result:
            case dict():
                counts[result["status"]] = counts.get(result["status"], 0) + 1
                print(f"[INFO] {result['status']}: {result['key']} {counts}")

            case _:
                counts["error"] += 1
                print(f"[ERROR] {result!r}")

    print(f"[SUMMARY] {counts}")

    return counts


@app.local_entrypoint()
def main(max_files: int = 0) -> None:
    call = run_all.spawn(max_files)

    print(f"[INFO] Spawned run_all (call id {call.object_id}); safe to disconnect")
    print("[INFO] Check progress: modal volume ls cmu-transcripts")

